{
  "findings": [
    {
      "ref": "[D188]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate can be bypassed by entering a birth year that allows full access.",
      "stance": "risk",
      "quote": "If the game registers that you are under 13 then certain elements are locked, including making in-game purchases. However, it is very easy for a child to be aware of these restrictions and choose to enter a birth year that allows them full access to all the features."
    },
    {
      "ref": "[D188]",
      "area": "money",
      "claim": "A parent reports that Minecraft has optional purchases like texture packs, skin packs, and Realms subscriptions.",
      "stance": "risk",
      "quote": "Once you have bought Minecraft you can then play the game without any compulsory additional spend, such as any kind of subscription fees or hidden costs. However, there are certain additional features that can be purchased. * Texture and skin packs: Texture packs are buyable ‘packs’ that change the look of your Minecraft blocks, ... Skin packs are the same, only they change the appearance of your character. * Minecraft Realms: Minecraft Realms is an online membership for Minecraft that allows you to operate your own multiplayer servers."
    },
    {
      "ref": "[D188]",
      "area": "data",
      "claim": "A parent reports that Minecraft uses cookies and may share data with third parties as described in its privacy policy.",
      "stance": "risk",
      "quote": "We use cookies to deliver our services. By using our website, you agree to the use of cookies as described on our [Privacy Policy](/privacy-policy) and [Cookie Policy](/cookie-policy)."
    },
    {
      "ref": "[D188]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with a child through multiplayer servers if enabled.",
      "stance": "risk",
      "quote": "When joining a multiplayer server, Minecraft will display a disclaimer telling your child that they may be exposed to open chatrooms that have not been rated (and therefore contain language or content suitable for all ages). Through Minecraft itself players can only communicate through a text chat, other applications such as Skype or Discord can allow your child to audibly talk with friends."
    },
    {
      "ref": "[D188]",
      "area": "content",
      "claim": "A parent reports that the game contains mild cartoonish violence with monsters disappearing in a puff of smoke and no blood.",
      "stance": "neutral",
      "quote": "The combat within the game is very simple, with damage being taken off of your health bar if you are hit by a monster or their weapon (and vice versa if you are attacking a monster). If you choose to fight, hearts appear around the monster to show damage is being taken instead of any visible injuries or blood."
    }
  ]
}
